    async Task RefreshServer(){
        if(serverQuerying)return;serverQuerying=true;
        try{string address=serverAddress;ServerStatusResult r=await Task.Run(()=>ServerStatus.Query(address));serverState.Text="● "+r.Summary;serverState.ForeColor=r.online?MacTheme.Blue:Color.FromArgb(235,110,110);serverAddressLabel.Text=address+(String.IsNullOrEmpty(r.name)?"":"\n"+r.name);}
        catch{serverState.Text="● Нет данных";serverState.ForeColor=MacTheme.Muted;}
        finally{serverQuerying=false;}
    }
